 1→import { TestBed } from '@angular/core/testing';
 2→import { HomeComponent } from './home';
 3→import { provideRouter } from '@angular/router';
 4→
 5→describe('HomeComponent', () => {
 6→  beforeEach(async () => {
 7→    await TestBed.configureTestingModule({
 8→      imports: [HomeComponent],
 9→      providers: [provideRouter([])],
10→    }).compileComponents();
11→  });
12→
13→  it('should display a hero tagline mentioning free guitar training', () => {
14→    const fixture = TestBed.createComponent(HomeComponent);
15→    fixture.detectChanges();
16→
17→    const tagline = fixture.nativeElement.querySelector('[data-testid="hero-tagline"]');
18→    expect(tagline).toBeTruthy();
19→    const text = tagline.textContent.toLowerCase();
20→    expect(text).toContain('free');
21→    expect(text).toContain('guitar');
22→  });
23→
24→  it('should display four feature highlights covering fretboard, quiz, warm-up and progression', () => {
25→    const fixture = TestBed.createComponent(HomeComponent);
26→    fixture.detectChanges();
27→
28→    const items = fixture.nativeElement.querySelectorAll('[data-testid="feature-item"]');
29→    expect(items.length).toBe(4);
30→
31→    const allText = Array.from(items)
32→      .map((el: any) => el.textContent.toLowerCase())
33→      .join(' ');
34→
35→    expect(allText).toContain('fretboard');
36→    expect(allText).toContain('quiz');
37→    expect(allText).toContain('warm-up');
38→    expect(allText).toContain('progress');
39→  });
40→
41→  it('should display a title and description for each feature highlight', () => {
42→    const fixture = TestBed.createComponent(HomeComponent);
43→    fixture.detectChanges();
44→
45→    const items = fixture.nativeElement.querySelectorAll('[data-testid="feature-item"]');
46→
47→    items.forEach((item: HTMLElement) => {
48→      const title = item.querySelector('.features__title');
49→      const description = item.querySelector('.features__description');
50→      expect(title).toBeTruthy();
51→      expect(title!.textContent!.trim().length).toBeGreaterThan(0);
52→      expect(description).toBeTruthy();
53→      expect(description!.textContent!.trim().length).toBeGreaterThan(0);
54→    });
55→  });
56→
57→  it('should have a CTA link to /learn with "Start Learning" text using Taiga UI button', () => {
58→    const fixture = TestBed.createComponent(HomeComponent);
59→    fixture.detectChanges();
60→
61→    const cta = fixture.nativeElement.querySelector('[data-testid="cta-learn"]');
62→    expect(cta).toBeTruthy();
63→    expect(cta.textContent.toLowerCase()).toContain('start learning');
64→    expect(cta.getAttribute('routerLink')).toBe('/learn');
65→    expect(cta.hasAttribute('tuiButton') || cta.getAttribute('tuiButton') !== null).toBe(true);
66→  });
67→});
