 1→import { test, expect } from '@playwright/test';
 2→
 3→test.describe('Homepage', () => {
 4→  test('should display hero, features and CTA linking to learn page', async ({ page }) => {
 5→    await page.goto('/');
 6→
 7→    const hero = page.getByTestId('hero-section');
 8→    await expect(hero).toBeVisible();
 9→
10→    // asserts English locale content
11→    const tagline = hero.getByTestId('hero-tagline');
12→    await expect(tagline).toBeVisible();
13→    await expect(tagline).toContainText(/free/i);
14→    await expect(tagline).toContainText(/guitar/i);
15→
16→    const features = page.getByTestId('feature-highlights');
17→    await expect(features).toBeVisible();
18→
19→    const featureItems = features.getByTestId('feature-item');
20→    await expect(featureItems).not.toHaveCount(0);
21→
22→    const cta = page.getByTestId('cta-learn');
23→    await expect(cta).toBeVisible();
24→    await expect(cta).toHaveText(/start learning/i);
25→
26→    await cta.click();
27→    await expect(page).toHaveURL('/learn');
28→  });
29→});
