@use '@taiga-ui/core/styles/taiga-ui-local';
@use 'app/theme/theme';
@use 'app/theme/variables' as gt;

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: gt.$font-family;
  color: var(--gt-text);
  background: var(--tui-background-base);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

// Fade-in animation for page sections
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(1.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in {
  animation: fadeInUp 0.6s ease-out both;

  @for $i from 1 through 6 {
    &:nth-child(#{$i}) {
      animation-delay: #{$i * 0.1}s;
    }
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

input.content:
@use '../theme/variables' as gt;

:host {
  display: block;
}

// Hero section — full-width gradient background
.hero {
  background: var(--gt-hero-bg);
  text-align: center;
  padding: gt.$section-padding;
  padding-top: 6rem;
  padding-bottom: 6rem;
  animation: fadeInUp 0.6s ease-out both;

  &__tagline {
    font-size: gt.$hero-font-size;
    font-weight: 800;
    color: var(--gt-hero-text);
    margin: 0 0 1.25rem;
    line-height: 1.15;
    letter-spacing: -0.02em;
    max-width: gt.$max-width;
    margin-left: auto;
    margin-right: auto;
  }

  &__subtitle {
    font-size: gt.$subtitle-font-size;
    color: var(--gt-hero-subtitle);
    margin: 0;
    line-height: 1.6;
    max-width: 640px;
    margin-left: auto;
    margin-right: auto;
  }
}

// Feature highlights — alternating background
.features {
  background: var(--gt-surface-alt);
  padding: gt.$section-padding;

  &__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    max-width: gt.$max-width;
    margin: 0 auto;
  }

  &__heading {
    text-align: center;
    font-size: 2rem;
    font-weight: 700;
    color: var(--gt-primary);
    margin: 0 0 3rem;
    max-width: gt.$max-width;
    margin-left: auto;
    margin-right: auto;
  }

  &__item {
    background: var(--gt-surface);
    border-radius: gt.$border-radius;
    padding: 2rem;
    box-shadow: var(--gt-card-shadow);
    transition:
      transform gt.$transition-base,
      box-shadow gt.$transition-base;
    animation: fadeInUp 0.6s ease-out both;

    &:nth-child(1) { animation-delay: 0.15s; }
    &:nth-child(2) { animation-delay: 0.25s; }
    &:nth-child(3) { animation-delay: 0.35s; }
    &:nth-child(4) { animation-delay: 0.45s; }

    &:hover {
      transform: translateY(-4px);
      box-shadow: var(--gt-card-shadow-hover);
    }
  }

  &__icon {
    font-size: 2rem;
    margin-bottom: 1rem;
    display: block;
  }

  &__title {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--gt-text);
    margin: 0 0 0.75rem;
  }

  &__description {
    color: var(--gt-text-secondary);
    margin: 0;
    line-height: 1.7;
    font-size: 0.95rem;
  }
}

// CTA section
.cta {
  background: var(--gt-surface);
  text-align: center;
  padding: gt.$section-padding;
  animation: fadeInUp 0.6s ease-out both;
  animation-delay: 0.5s;

  &__button {
    display: inline-block;
    position: relative;
    overflow: hidden;
    font-size: 1.15rem;
    padding: 0.85rem 2.5rem;
    border-radius: gt.$border-radius;
    background: linear-gradient(135deg, gt.$accent-orange, gt.$accent-orange-light);
    color: gt.$neutral-white;
    font-weight: 700;
    border: none;
    cursor: pointer;
    text-decoration: none;
    transition:
      transform gt.$transition-base,
      box-shadow gt.$transition-base;

    // Shine effect on hover
    &::after {
      content: '';
      position: absolute;
      top: -50%;
      left: -75%;
      width: 50%;
      height: 200%;
      background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.3),
        transparent
      );
      transform: skewX(-25deg);
      transition: left 0.6s ease;
    }

    &:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(253, 141, 50, 0.4);

      &::after {
        left: 125%;
      }
    }

    &:active {
      transform: translateY(0);
    }
  }
}

// Responsive
@media (max-width: 768px) {
  .hero {
    padding: gt.$section-padding-mobile;
    padding-top: 4rem;
    padding-bottom: 4rem;

    &__tagline {
      font-size: gt.$hero-font-size-mobile;
    }

    &__subtitle {
      font-size: 1.1rem;
    }
  }

  .features {
    padding: gt.$section-padding-mobile;

    &__heading {
      font-size: 1.5rem;
      margin-bottom: 2rem;
    }

    &__grid {
      grid-template-columns: 1fr;
      gap: 1.5rem;
    }
  }

  .cta {
    padding: gt.$section-padding-mobile;
  }
}

