 66→    color: var(--gt-primary);
 67→    margin: 0 0 3rem;
 68→    max-width: gt.$max-width;
 69→    margin-left: auto;
 70→    margin-right: auto;
 71→  }
 72→
 73→  &__item {
 74→    background: var(--gt-surface);
 75→    border-radius: gt.$border-radius;
 76→    padding: gt.$card-padding;
 77→    box-shadow: var(--gt-card-shadow);
 78→    transition:
 79→      transform gt.$transition-base,
 80→      box-shadow gt.$transition-base;
 81→    animation: fadeInUp 0.6s ease-out both;
 82→
 83→    @for $i from 1 through 4 {
 84→      &:nth-child(#{$i}) {
 85→        animation-delay: #{0.05 + $i * 0.1}s;
 86→      }
 87→    }
 88→
 89→    &:hover {
 90→      transform: translateY(-4px);
 91→      box-shadow: var(--gt-card-shadow-hover);
 92→    }
 93→  }
 94→
 95→  &__icon {
 96→    font-size: gt.$feature-icon-size;
 97→    margin-bottom: 1rem;
 98→    display: block;
 99→  }
100→
101→  &__title {
102→    font-size: gt.$feature-title-size;
103→    font-weight: 700;
104→    color: var(--gt-text);
105→    margin: 0 0 0.75rem;
106→  }
107→
108→  &__description {
109→    color: var(--gt-text-secondary);
110→    margin: 0;
111→    line-height: 1.7;
112→    font-size: gt.$feature-description-size;
113→  }
114→}
115→
116→// CTA section
117→// Note: The CTA button uses custom styling instead of Taiga UI's tuiButton directive
118→// because the design spec requires a shine-effect on hover (pseudo-element animation),
119→// which is not achievable through Taiga UI's button API. This is a deliberate deviation.
120→.cta {
121→  background: var(--gt-surface);
122→  text-align: center;
123→  padding: gt.$section-padding;
124→  animation: fadeInUp 0.6s ease-out both;
125→  animation-delay: 0.5s;
126→
127→  &__button {
128→    display: inline-block;
129→    position: relative;
130→    overflow: hidden;
131→    font-size: 1.15rem;
132→    padding: 0.85rem 2.5rem;
133→    border-radius: gt.$border-radius;
134→    background: linear-gradient(135deg, gt.$accent-orange, gt.$accent-orange-light);
135→    color: gt.$neutral-white;
136→    font-weight: 700;
137→    border: none;
138→    cursor: pointer;
139→    text-decoration: none;
140→    transition:
141→      transform gt.$transition-base,
142→      box-shadow gt.$transition-base;
143→
144→    // Shine effect on hover — uses transform instead of left for compositor-only animation
145→    &::after {
146→      content: '';
147→      position: absolute;
148→      top: -50%;
149→      left: 0;
150→      width: 50%;
151→      height: 200%;
152→      background: linear-gradient(
153→        90deg,
154→        transparent,
155→        rgba(255, 255, 255, 0.3),
156→        transparent
157→      );
158→      transform: translateX(-150%) skewX(-25deg);
159→      transition: transform 0.6s ease;
160→    }
161→
162→    &:hover {
163→      transform: translateY(-2px);
164→      box-shadow: 0 4px 20px rgba(253, 141, 50, 0.4);
165→
166→      &::after {
167→        transform: translateX(250%) skewX(-25deg);
168→      }
169→    }
170→
171→    &:active {
172→      transform: translateY(0);
173→    }
174→  }
175→}
176→
177→// Responsive
178→@media (max-width: 768px) {
179→  .hero {
180→    padding: 4rem 1rem;
181→
182→    &__tagline {
183→      font-size: gt.$hero-font-size-mobile;
184→    }
185→
186→    &__subtitle {
187→      font-size: 1.1rem;
188→    }
189→  }
190→
191→  .features {
192→    padding: gt.$section-padding-mobile;
193→
194→    &__heading {
195→      font-size: gt.$feature-heading-size-mobile;
196→      margin-bottom: gt.$feature-grid-gap;
197→    }
198→
199→    &__grid {
200→      grid-template-columns: 1fr;
201→      gap: 1.5rem;
202→    }
203→  }
204→
205→  .cta {
206→    padding: gt.$section-padding-mobile;
207→  }
208→}
